import type { SurveyContent } from '../lib/types'
import raw from './content.json'

/**
 * Generated by `npm run content` from the content sheet. Edit the sheet,
 * not content.json.
 */
export const content = raw as SurveyContent

export function setting(key: string, fallback = ''): string {
  return content.settings[key] || fallback
}
